"""QQ-姿态库的 HTTP 路由：索引、图片、缩略图、导入、删除。

前端画廊通过 ``/qq_gulipose/*`` 取数据；所有写操作都限制在用户数据目录里，
不碰插件目录，也不接受任意路径。
"""

from __future__ import annotations

import io
import json
from pathlib import Path
from typing import Any

try:  # ComfyUI 运行时一定有 aiohttp；独立导入测试时可能没有
    from aiohttp import web
except Exception:  # pragma: no cover - 测试环境
    class _NoWeb:  # 占位：模块能被导入，register() 里自然拿不到 PromptServer
        pass

    web = _NoWeb()  # type: ignore[assignment]

try:  # 包内导入（ComfyUI 正常加载）
    from . import guli_pose_db as db
except ImportError:  # pragma: no cover - 测试里按独立模块加载
    import guli_pose_db as db  # type: ignore[no-redef]

PREFIX = "/qq_gulipose"
#: 单张上传上限 200 MB。
MAX_UPLOAD = 200 * 1024 * 1024


def _json(data: Any) -> web.Response:
    return web.json_response(data, dumps=lambda obj: json.dumps(obj, ensure_ascii=False))


def _index_payload(lib: str) -> dict[str, Any]:
    data = db.index(lib)
    return {
        "lib": lib,
        "name": db.lib_name(lib),
        "generated": data.get("generated"),
        "angles": data.get("angles") or [],
        "series": data.get("series") or [],
        "poses": data.get("poses") or [],
        "all": db.ALL,
        "randomAngle": db.RANDOM_ANGLE,
        "customSeries": db.CUSTOM_SERIES_KEY,
        "customDir": str(db.custom_dir(lib)),
    }


def _file_response(path: Path) -> web.StreamResponse:
    if not path.is_file():
        raise web.HTTPNotFound(text="文件不存在")
    return web.FileResponse(path)


def _safe_custom(name: str, lib: str) -> Path:
    """custom/ 下的目标路径；越界一律拒绝。"""
    root = db.custom_dir(lib).resolve()
    target = (root / Path(str(name or "")).name).resolve()
    if target.parent != root:
        raise web.HTTPForbidden(text="越界路径")
    return target


def _register_lib(app: web.Application, lib: str) -> None:
    def get_index(_request: web.Request) -> web.Response:
        return _json(_index_payload(lib))

    def get_image(request: web.Request) -> web.StreamResponse:
        name = request.match_info.get("name", "")
        root = db.LIB_DIRS[lib]["builtin"].resolve()
        target = (root / Path(name).name).resolve()
        if target.parent != root:
            raise web.HTTPForbidden(text="越界路径")
        return _file_response(target)

    def get_custom_image(request: web.Request) -> web.StreamResponse:
        return _file_response(_safe_custom(request.match_info.get("name", ""), lib))

    def get_thumb(request: web.Request) -> web.StreamResponse:
        name = request.match_info.get("name", "")
        path = db.ensure_thumb(name, lib)
        if path is None:
            raise web.HTTPNotFound(text="缩略图不可用")
        return web.FileResponse(path)

    def get_custom_thumb(request: web.Request) -> web.StreamResponse:
        name = request.match_info.get("name", "")
        path = db.ensure_thumb(name, lib, custom=True)
        if path is None:
            raise web.HTTPNotFound(text="缩略图不可用")
        return web.FileResponse(path)

    async def upload(request: web.Request) -> web.Response:
        reader = await request.multipart()
        saved: list[str] = []
        name = cat = angle = ""
        files: list[tuple[str, bytes]] = []
        async for part in reader:
            if part.name == "name":
                name = (await part.text()).strip()
            elif part.name == "cat":
                cat = (await part.text()).strip()
            elif part.name == "angle":
                angle = (await part.text()).strip()
            elif part.name == "file":
                data = await part.read(decode=False)
                if len(data) > MAX_UPLOAD:
                    raise web.HTTPRequestEntityTooLarge(text="图片太大")
                files.append((part.filename or "pose.png", data))
        for filename, data in files:
            saved.append(db.save_custom(filename, data, name, cat, angle, lib))
        if not saved:
            raise web.HTTPBadRequest(text="没有收到图片")
        return _json({"saved": saved, "index": _index_payload(lib)})

    async def delete(request: web.Request) -> web.Response:
        payload = await request.json()
        name = str(payload.get("name") or "")
        if not db.delete_custom(name, lib):
            raise web.HTTPNotFound(text="文件不存在")
        return _json({"deleted": name, "index": _index_payload(lib)})

    def list_all(_request: web.Request) -> web.Response:
        return _json(_index_payload(lib))

    routes = app.router
    routes.get(f"{PREFIX}/{lib}/index.json")(get_index)
    routes.get(f"{PREFIX}/{lib}/all")(list_all)
    routes.get(f"{PREFIX}/{lib}/img/{{name}}")(get_image)
    routes.get(f"{PREFIX}/{lib}/custom/{{name}}")(get_custom_image)
    routes.get(f"{PREFIX}/{lib}/thumbs/{{name}}")(get_thumb)
    routes.get(f"{PREFIX}/{lib}/custom/thumbs/{{name}}")(get_custom_thumb)
    routes.post(f"{PREFIX}/{lib}/custom/upload")(upload)
    routes.post(f"{PREFIX}/{lib}/custom/delete")(delete)


def register() -> None:
    """挂到 ComfyUI 的 PromptServer 上；没有运行时就静默跳过。"""
    try:
        from server import PromptServer
    except Exception:
        return
    instance = getattr(PromptServer, "instance", None)
    if instance is None:
        return
    app = getattr(instance, "app", None)
    if app is None:
        return
    for lib in db.LIB_DIRS:
        _register_lib(app, lib)


__all__ = ["PREFIX", "register"]
